#include "eos_regression_evaluator.hpp"
#include "pure_saturation.hpp"

#include <cassert>
#include <cmath>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <utility>
#include <variant>

using epcsaft::EosRegressionFamily;
using epcsaft::EosRegressionSpec;
using epcsaft::NativeActiveCoordinate;
using epcsaft::NativeModel;
using epcsaft::NativeParameters;
using epcsaft_engine::interfaces::Evaluation;
using epcsaft_engine::interfaces::EvaluationFailure;

namespace {

std::string digest(char value) { return "sha256:" + std::string(64, value); }

NativeModel model() {
    NativeParameters parameters;
    parameters.segment_count = {2.002};
    parameters.sigma_constant = {3.6184};
    parameters.dispersion_energy_over_k = {208.11};
    parameters.k_ij = {0.0};
    parameters.k_ij_reciprocal_temperature_slope = {0.0};
    parameters.k_ij_reference_temperature_k = {0.0};
    parameters.l_ij = {0.0};
    parameters.molar_mass_kg_per_mol = {0.044096};
    parameters.charge_number = {0};
    parameters.relative_permittivity = {0.0};
    parameters.permittivity_reference_temperature_k = {0.0};
    parameters.ion_fraction_suppression_coefficient = 0.0;
    parameters.packing_diameter_angstrom = {0.0};
    parameters.debye_huckel_diameter_angstrom = {0.0};
    parameters.born_diameter_angstrom = {0.0};
    parameters.solvation_factor = {0.0};
    parameters.ionic_region_relative_permittivity = 0.0;
    parameters.born_c_shell = 0.0;
    parameters.born_c_dielectric = 0.0;
    parameters.electrolyte_model = epcsaft::ELECTROLYTE_MODEL_NONE;
    parameters.dielectric_volume_m3_per_mol = {0.0};
    parameters.dielectric_temperature_k = {0.0};
    parameters.ion_specific_suppression_coefficient = {0.0};
    parameters.dipole_scaling_debye2 = {0.0};
    parameters.polarizability_scaling_angstrom3 = {0.0};
    parameters.correlation_integral_parameter = {0.0};
    parameters.relative_permittivity_formulation =
        epcsaft::RELATIVE_PERMITTIVITY_FORMULATION_NONE;
    return NativeModel(std::move(parameters))
        .with_parameter_identities({"propane"}, {})
        .with_eos_metadata(
            digest('a'), std::numeric_limits<double>::quiet_NaN(),
            std::numeric_limits<double>::quiet_NaN(),
            std::numeric_limits<double>::quiet_NaN(),
            std::numeric_limits<double>::quiet_NaN(),
            std::numeric_limits<double>::quiet_NaN(), digest('b'), digest('c'),
            digest('d'), digest('e'), std::numeric_limits<double>::quiet_NaN(),
            std::numeric_limits<double>::quiet_NaN(),
            std::numeric_limits<double>::quiet_NaN(),
            std::numeric_limits<double>::quiet_NaN(), "", "");
}

NativeActiveCoordinate active() {
    return {"component/propane/segment_count", "segment_count",
            "component-property", {0}, {}, {}, 2.002, 0.0};
}

EosRegressionSpec spec(
    EosRegressionFamily family, std::vector<std::string> rows,
    std::vector<double> composition = {1.0}
) {
    const auto coordinate = active();
    return {
        family, 300.0, 1200.0, std::move(composition),
        {coordinate.identity}, {"dimensionless"}, {"physical"},
        std::move(rows),
        "sha256:8cc74e4f68f6f7754e5b16d7ef05cc4997d7b6379513cd3f8811f8a5260beff0",
        digest('1'), digest('2')
    };
}

const Evaluation& accepted(
    const epcsaft_engine::interfaces::EvaluationResult& result
) {
    assert(std::holds_alternative<Evaluation>(result));
    return std::get<Evaluation>(result);
}

void rejects_invalid_contracts(const NativeModel& baseline) {
    const auto coordinate = active();
    auto forged = spec(EosRegressionFamily::FixedState, {"pressure_pa"});
    forged.parameter_contract_fingerprint = digest('f');
    bool contract_rejected = false;
    try {
        static_cast<void>(epcsaft::compile_eos_regression_evaluator(
            baseline, forged, {coordinate}));
    } catch (const std::invalid_argument&) {
        contract_rejected = true;
    }
    assert(contract_rejected);

    auto mismatched = coordinate;
    mismatched.family = "dispersion_energy_over_k";
    bool family_rejected = false;
    try {
        static_cast<void>(epcsaft::compile_eos_regression_evaluator(
            baseline, spec(EosRegressionFamily::FixedState, {"pressure_pa"}),
            {mismatched}));
    } catch (const std::invalid_argument&) {
        family_rejected = true;
    }
    assert(family_rejected);

    bool normalized_rejected = false;
    try {
        static_cast<void>(epcsaft::compile_eos_regression_evaluator(
            baseline, spec(EosRegressionFamily::FixedState, {"pressure_pa"},
                           {0.4}), {coordinate}));
    } catch (const std::invalid_argument&) {
        normalized_rejected = true;
    }
    assert(normalized_rejected);
}

void fixed_state() {
    const auto coordinate = active();
    const auto baseline = model();
    auto compiled = epcsaft::compile_eos_regression_evaluator(
        baseline,
        spec(EosRegressionFamily::FixedState,
             {"pressure_pa", "helmholtz_over_rt_reference_amount"}),
        {coordinate});
    const auto* owner = dynamic_cast<const epcsaft::EosOwnerEvaluator*>(
        compiled.evaluator.get());
    assert(owner != nullptr && compiled.sidecar.get() == &owner->sidecar());
    const auto exact_result = compiled.evaluator->evaluate({2.002}, true);
    const auto& exact = accepted(exact_result);
    const auto direct = baseline.with_active_coordinates({coordinate})
        .evaluate_phase_derivatives(300.0, {1.0}, 1.0 / 1200.0,
                                    {coordinate}, 2);
    assert(exact.predictions[0] == direct.pressure_pa);
    assert(exact.predictions[1] == direct.helmholtz_over_rt_reference_amount);
    assert(exact.jacobian[0] == -8.31446261815324 * 300.0
        * direct.hessian[1 * 3 + 2]);
    assert(exact.jacobian[1] == direct.gradient[2]);
    const auto bad = compiled.evaluator->evaluate(
        {std::numeric_limits<double>::quiet_NaN()}, true);
    assert(std::get<EvaluationFailure>(bad).code == "eos_domain_rejection");
    rejects_invalid_contracts(baseline);
}

void pure_saturation() {
    const auto coordinate = active();
    const auto baseline = model();
    auto compiled = epcsaft::compile_eos_regression_evaluator(
        baseline,
        spec(EosRegressionFamily::PureSaturation,
             {"saturation_pressure_pa", "vapor_molar_density_mol_per_m3",
              "liquid_molar_density_mol_per_m3"}),
        {coordinate});
    const auto exact_result = compiled.evaluator->evaluate({2.002}, true);
    const auto& exact = accepted(exact_result);
    const auto direct = epcsaft::solve_local_saturation_active(
        baseline, 300.0, {coordinate});
    assert(direct.solve.accepted);
    assert(exact.predictions[0] == direct.solve.evaluation.saturation_pressure_pa);
    assert(exact.predictions[1] == 1.0 / direct.solve.evaluation.vapor.volume_m3);
    assert(exact.predictions[2] == 1.0 / direct.solve.evaluation.liquid.volume_m3);
    for (std::size_t index = 0; index < exact.jacobian.size(); ++index) {
        assert(exact.jacobian[index] == direct.derivatives[index]);
    }
}

}  // namespace

int main() {
    fixed_state();
    pure_saturation();
    std::cout << "issue151_direct_check: PASS\n";
}
